using AuthService.Infrastructure.Tokens; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.Extensions.Options;
namespace AuthService.Api.Security; public static class JwtBearerSetup { public static IServiceCollection AddJwtBearerSetup(this IServiceCollection s){s.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer();s.AddOptions<JwtBearerOptions>(JwtBearerDefaults.AuthenticationScheme).Configure<SigningKeyProvider,IOptions<JwtOptions>>((o,k,j)=>{var v=j.Value;o.MapInboundClaims=false;o.TokenValidationParameters=new(){ValidateIssuer=true,ValidIssuer=v.Issuer,ValidateAudience=true,ValidAudience=v.Audience,ValidateIssuerSigningKey=true,IssuerSigningKey=k.Credentials.Key,ValidateLifetime=true,ClockSkew=TimeSpan.FromMinutes(1),NameClaimType="sub",RoleClaimType="role"};});return s;} }
